using UnityEngine;

namespace Astrea.GameStates;

public class NoTargetSelectionCastStateAction : BattleActionCastStatesAction
{
	protected void AllTargetsCastAction()
	{
		ActionFace actionFace = base.actionInstance.ActionFace;
		_ = actionFace.BattleAction;
		CastAction(delegate(GameObject source)
		{
			actionFace.BattleAction.AreaCastTargetAmount(actionTargets, actionFace.ModifiedActionValue, source);
		}, delegate(GameObject source)
		{
			actionFace.BattleAction.AreaCastTarget(actionTargets, source);
		});
		for (int i = 0; i < actionTargets.Count; i++)
		{
			actionTargets[i].GetComponentInChildren<TargetInstance>().OnClick();
		}
	}

	protected void NoTargetCastAction()
	{
		ActionFace actionFace = base.actionInstance.ActionFace;
		_ = actionFace.BattleAction;
		CastAction(delegate(GameObject source)
		{
			actionFace.BattleAction.CastAmount(actionFace.ModifiedActionValue, source);
		}, delegate(GameObject source)
		{
			actionFace.BattleAction.Cast(source);
		});
	}

	protected void RandomTargetCastAction()
	{
		ActionFace actionFace = base.actionInstance.ActionFace;
		_ = actionFace.BattleAction;
		if (actionTargets.Count > 0)
		{
			GameObject targetGameObject = actionTargets.First();
			CastAction(delegate(GameObject source)
			{
				actionFace.BattleAction.CastTargetAmount(targetGameObject, actionFace.ModifiedActionValue, source);
			}, delegate(GameObject source)
			{
				actionFace.BattleAction.CastTarget(targetGameObject, source);
			}, targetGameObject);
			targetGameObject.GetComponentInChildren<TargetInstance>().OnClick();
		}
		else
		{
			ActionCasted();
			ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
		}
	}
}
